mapper.select:
SELECT COMPANY_CODE, USER_ID, USER_NAME, DEPT, JOB_TITLE, POSITION, USER_STATUS FROM TB_USER_MASTER WHERE COMPANY_CODE = #{companyCode}
AND USER_NAME LIKE '%' || #{userName} || '%'
AND DEPT = #{dept}
AND POSITION = #{position}
ORDER BY USER_NAME

SELECT M.MENU_CODE AS menuCode, M.MENU_NAME AS menuName, M.PARENT_MENU_CODE AS parentCode, M.SYSTRM_TYPE AS systemType, NVL(M.SORT_ORDER, 0) AS sortOrder,
AM.ACTION_CODE AS actionCode, AM.ACTION_NAME AS actionName,
RA.AUTH_YN AS roleAuthYn, UA.AUTH_YN AS userAuthYn, NVL(UA.AUTH_YN, RA.AUTH_YN) AS authYn
FROM TB_MENU_MASTER M
/* 메뉴별 사용 가능한 액션 */ JOIN TB_MENU_ACTION_MASTER AM ON M.COMPANY_CODE = AM.COMPANY_CODE AND M.MENU_CODE = AM.MENU_CODE
/* ROLE 기준 권한 (여러 ROLE → MAX(Y/N)) */ LEFT JOIN ( SELECT COMPANY_CODE, MENU_CODE, ACTION_CODE, MAX(AUTH_YN) AS AUTH_YN FROM TB_ROLE_MENU_AUTH WHERE COMPANY_CODE = #{companyCode} AND ROLE_CODE IN ( SELECT ROLE_CODE FROM TB_USER_ROLE WHERE COMPANY_CODE = #{companyCode} AND USER_ID = #{userId} ) GROUP BY COMPANY_CODE, MENU_CODE, ACTION_CODE ) RA ON M.COMPANY_CODE = RA.COMPANY_CODE AND M.MENU_CODE = RA.MENU_CODE AND AM.ACTION_CODE = RA.ACTION_CODE
/* USER 오버라이드 권한 */ LEFT JOIN TB_USER_MENU_AUTH UA ON M.COMPANY_CODE = UA.COMPANY_CODE AND M.MENU_CODE = UA.MENU_CODE AND AM.ACTION_CODE = UA.ACTION_CODE AND UA.USER_ID = #{userId}
WHERE M.COMPANY_CODE = #{companyCode} AND M.USE_YN = 'Y'
ORDER BY M.SYSTRM_TYPE, M.MENU_LEVEL, M.SORT_ORDER, AM.SORT_ORDER

mapper.delete:
DELETE FROM TB_USER_MENU_AUTH
WHERE COMPANY_CODE = #{companyCode}
  AND USER_ID      = #{userId}
